import{renderCalendar}from'../../widgets/calendar.js';import{renderTodo}from'../../widgets/todo.js';import{renderHistory}from'../../widgets/history.js';import{navigateTo}from'../../shared/navigation-helper.js';function renderSidebar(settings){const sidebar=document.getElementById('sidebar');const isLeft=settings.sidebarPosition==='left';sidebar.className='sidebar '+(isLeft?'left':'right');document.body.classList.toggle('sidebar-left',isLeft);document.body.classList.toggle('sidebar-right',!isLeft);document.body.classList.add('sidebar-open');['left','right'].forEach((side)=>{const handle=document.createElement('div');handle.className='sidebar-draghandle '+side;handle.title='Drag to move the sidebar to the '+side+' side';handle.draggable=true;handle.addEventListener('dragstart',(e)=>{e.dataTransfer.setData(SIDEBAR_DRAG_TYPE,side);e.dataTransfer.setData('text/plain','sidebar');e.dataTransfer.effectAllowed='move';});sidebar.appendChild(handle);});const sidebarContent=document.createElement('div');sidebarContent.className='sidebar-content';sidebar.appendChild(sidebarContent);['clock','weather'].forEach(id=>{const el=document.getElementById(id);if(!el)return;const widget=document.createElement('div');widget.className=`widget widget-${id}`;widget.appendChild(el);sidebarContent.appendChild(widget);});const widgetRenderers={calendar:renderCalendar,todo:renderTodo,history:renderHistory};const selectedWidgets=Array.isArray(settings.sidebarWidgets)?settings.sidebarWidgets:[];selectedWidgets.forEach(widgetId=>{const widgetContent=widgetRenderers[widgetId];if(!widgetContent)return;const widgetContainer=document.createElement('div');widgetContainer.classList.add('widget');widgetContainer.id=`widget-${widgetId}`;widgetContainer.append(widgetContent());sidebarContent.appendChild(widgetContainer);});const footer=document.createElement('div');footer.className='sidebar-footer';const customizeBtn=document.createElement('button');customizeBtn.type='button';customizeBtn.className='sidebar-footer-btn';customizeBtn.title='Customize';customizeBtn.innerHTML='<span class="sidebar-footer-icon">⚙</span><span>Customize</span>';customizeBtn.addEventListener('click',()=>{navigateTo('../options/options.html',{newTab:false});});const themeBtn=document.createElement('button');themeBtn.type='button';themeBtn.className='sidebar-footer-btn sidebar-theme-btn';themeBtn.title='Change theme';themeBtn.innerHTML='<span class="theme-icon"></span><span class="theme-label">System</span>';themeBtn.addEventListener('click',()=>{const current=localStorage.getItem("theme")||"system";const next=current==="system"?"dark":(current==="dark"?"light":"system");localStorage.setItem("theme",next);if(typeof applyTheme==="function")applyTheme(next);});footer.appendChild(customizeBtn);footer.appendChild(themeBtn);sidebar.appendChild(footer);if(typeof applyTheme==="function")applyTheme(localStorage.getItem("theme")||"system");}
const SIDEBAR_DRAG_TYPE='application/x-bm-sidebar';function setSidebarSide(side){try{const stored=JSON.parse(localStorage.getItem('settings'))||{};stored.sidebarPosition=side;localStorage.setItem('settings',JSON.stringify(stored));}catch{}
const isLeft=side==='left';document.body.classList.toggle('sidebar-left',isLeft);document.body.classList.toggle('sidebar-right',!isLeft);}
const sidebarCue=document.createElement('div');sidebarCue.className='sidebar-drop-cue hidden';document.body.appendChild(sidebarCue);const sidebarDragTypes=(e)=>[...((e.dataTransfer&&e.dataTransfer.types)||[])];document.addEventListener('dragover',(e)=>{if(!sidebarDragTypes(e).includes(SIDEBAR_DRAG_TYPE))return;e.preventDefault();sidebarCue.classList.remove('hidden','at-left','at-right');sidebarCue.classList.add(e.clientX<window.innerWidth/2?'at-left':'at-right');});document.addEventListener('dragend',()=>{sidebarCue.classList.add('hidden');sidebarCue.classList.remove('at-left','at-right');});document.addEventListener('drop',(e)=>{if(!sidebarDragTypes(e).includes(SIDEBAR_DRAG_TYPE))return;e.preventDefault();const dropLeft=e.clientX<window.innerWidth/2;sidebarCue.classList.add('hidden');sidebarCue.classList.remove('at-left','at-right');setSidebarSide(dropLeft?'left':'right');});export{renderSidebar};